        "YT": "1531,5038 1010,4732 513,4374 195,4107 236,4037 144,4004 77,3905 1290,2075 1376,2197 1401,2349 1464,2461 1261,2861 1400,2974 1315,3214 1406,3279 1261,3520 1297,3622 1276,3649 1330,3683 1315,3790 1344,3867 1334,3949 1290,3979 1310,4055 1249,4273 1303,4318 1360,4537 1322,4709 1542,4783 1516,4848 1530,5032 1531,5038",
    ]

    /// Parsed once, on first use.
    static let outlines: [String: [[CGPoint]]] = encoded.mapValues { blob in
        blob.split(separator: ";").map { ring in
            ring.split(separator: " ").compactMap { pair -> CGPoint? in
                let xy = pair.split(separator: ",")
                guard xy.count == 2,
                      let x = Double(xy[0]), let y = Double(xy[1]) else { return nil }
                return CGPoint(x: x / 10000, y: y / 10000)
            }
        }
    }

    /// Drawing order matters: the Maritimes have to land on top of their neighbours
    /// or a shared border can swallow them.
    static let codes: [String] = outlines.keys.sorted {
        area(of: $0) > area(of: $1)
    }

    static func path(for code: String, in rect: CGRect) -> Path {
        var path = Path()
        for ring in outlines[code] ?? [] where ring.count > 2 {
            path.move(to: point(ring[0], in: rect))
            for p in ring.dropFirst() { path.addLine(to: point(p, in: rect)) }
            path.closeSubpath()
        }
        return path
    }

    /// The region under a tap.
    ///
    /// Exact containment first, then the nearest centroid within a finger's width.
    /// Without the fallback, Prince Edward Island is under ten points across and
    /// effectively impossible to hit.
    static func hitTest(_ point: CGPoint, in rect: CGRect) -> String? {
        for code in codes.reversed() where path(for: code, in: rect).contains(point) {
            return code
        }
        var best: (code: String, distance: CGFloat)?
        for code in codes {
            let c = self.point(centroid(of: code), in: rect)
            let d = hypot(c.x - point.x, c.y - point.y)
            if d < 26, best == nil || d < best!.distance { best = (code, d) }
        }
        return best?.code
    }

    static func centroid(of code: String) -> CGPoint {
        guard let ring = outlines[code]?.first, !ring.isEmpty else { return .zero }
        let sum = ring.reduce(CGPoint.zero) { CGPoint(x: $0.x + $1.x, y: $0.y + $1.y) }
        return CGPoint(x: sum.x / CGFloat(ring.count), y: sum.y / CGFloat(ring.count))
    }

    private static func point(_ p: CGPoint, in rect: CGRect) -> CGPoint {
        CGPoint(x: rect.minX + p.x * rect.width, y: rect.minY + p.y * rect.height)
    }

    private static func area(of code: String) -> CGFloat {
        guard let ring = outlines[code]?.first else { return 0 }
        var sum: CGFloat = 0
        for i in ring.indices {
            let a = ring[i], b = ring[(i + 1) % ring.count]
            sum += a.x * b.y - b.x * a.y
        }
        return abs(sum) / 2
    }
}
